import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Endgame exploitation against cooperative opponents
    if n >= 97:
        opp_c = sum(1 for h in history if h[1] == 'C')
        if opp_c > n * 0.85:
            return 'D'

    last_me, last_opp = history[-1]

    # Tit-for-Tat core with noise forgiveness and strategic probing
    if last_opp == 'D':
        # If we were also D, we are in mutual defection. Try to break cycle.
        if last_me == 'D':
            # Check if opponent has been consistently D recently (hard defector)
            recent_d = sum(1 for h in history[-4:] if h[1] == 'D')
            if recent_d < 3:
                # Likely noise or temporary, try to reset cooperation
                return 'C'
            else:
                # Hard defector, stay in D
                return 'D'
        else:
            # We played C, they played D. Retaliate immediately.
            return 'D'

    # Opponent played C
    if last_me == 'C':
        # Mutual cooperation. Maintain it.
        # Small chance to probe/defect if opponent is very naive (always C)
        if n > 20:
            opp_c_count = sum(1 for h in history if h[1] == 'C')
            if opp_c_count == n:
                if rng.random() < 0.05:
                    return 'D'
        return 'C'
    else:
        # We played D, they played C. We exploited them.
        # Return to cooperation to avoid triggering permanent defection loop 
        # unless we suspect they are always-C and we want to keep exploiting.
        if n > 30:
             opp_c_count = sum(1 for h in history if h[1] == 'C')
             if opp_c_count > n * 0.95:
                 return 'D'
        return 'C'
